style.css:
@-moz-document domain("youtube.com") {
/* STEAMTUBE — Embedded Header Logo */
:root {
  --my-bg: #101923;
  --my-panel: #172735;
  --my-card: #1b3040;
  --my-blue: #1a9fff;
  --my-light-blue: #66c0f4;
  --my-text: #e5edf5;
  --my-muted: #91a8ba;
}

/* Steam-style backgrounds */
html, body, ytd-app {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* Steam-style header */
ytd-masthead {
  background: #101923 !important;
  border-bottom: 1px solid #29445a !important;
}

/* Replace YouTube logo */
ytd-masthead #logo,
ytd-logo #logo {
  width: 165px !important;
  min-width: 165px !important;
  height: 42px !important;
  overflow: hidden !important;
  position: relative !important;
}

ytd-masthead #logo svg,
ytd-logo #logo svg,
ytd-masthead #logo img,
ytd-logo #logo img {
  visibility: hidden !important;
}

ytd-masthead #logo::after,
ytd-logo #logo::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  width: 165px !important;
  height: 42px !important;
  background-image: url("data:image/jpeg;base64,") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* Steam search bar */
#container.ytd-searchbox {
  background: #0b141e !important;
  border: 1px solid #34536b !important;
  border-radius: 12px !important;
}

#container.ytd-searchbox:focus-within {
  border-color: var(--my-blue) !important;
  box-shadow: 0 0 12px #1a9fff55 !important;
}

/* Steam-style sidebar */
ytd-guide-renderer,
ytd-mini-guide-renderer {
  background: #121f2b !important;
}

ytd-guide-entry-renderer {
  border-radius: 8px !important;
  margin: 3px 8px !important;
}

ytd-guide-entry-renderer:hover {
  background: #263e51 !important;
}

/* Steam library video cards */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {
  background: var(--my-card) !important;
  border-radius: 14px !important;
  padding: 8px !important;
  transition: transform .2s ease !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {
  background: #25435a !important;
  transform: translateY(-3px) !important;
}

/* Rounded thumbnails */
ytd-thumbnail,
ytd-thumbnail img {
  border-radius: 12px !important;
  overflow: hidden !important;
}

/* Steam blue buttons */
yt-button-shape button,
#subscribe-button button {
  background: linear-gradient(135deg, #1684ce, #1a9fff) !important;
  color: white !important;
  border-radius: 9px !important;
}

/* Category chips */
yt-chip-cloud-chip-renderer {
  background: #1c3040 !important;
  border: 1px solid #34536b !important;
  border-radius: 9px !important;
}

yt-chip-cloud-chip-renderer[selected] {
  background: #12649d !important;
}

/* Video text */
#video-title {
  color: var(--my-text) !important;
}

#metadata,
#metadata-line,
ytd-video-meta-block {
  color: var(--my-muted) !important;
}

/* Player surroundings */
#player-container-outer,
#secondary,
#below {
  background: var(--my-bg) !important;
}

/* Blue hover glow */
a:hover,
yt-icon-button:hover {
  filter: drop-shadow(0 0 5px #1a9fff66) !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-track {
  background: #101923 !important;
}

::-webkit-scrollbar-thumb {
  background: #31536b !important;
  border-radius: 10px !important;
}
}
